        ["admin.load.failed"] = ["Some administrator data could not be loaded: {0}", "No se pudieron cargar algunos datos de administración: {0}", "Certaines données d’administration n’ont pas pu être chargées : {0}", "Impossibile caricare alcuni dati amministrativi: {0}", "Não foi possível carregar alguns dados administrativos: {0}", "일부 관리자 데이터를 불러오지 못했습니다: {0}", "一部の管理データを読み込めませんでした: {0}", "部分管理数据无法加载：{0}", "部分管理資料無法載入：{0}", "Không thể tải một số dữ liệu quản trị: {0}"],

        // Reports and service settings.
        ["admin.reports.unavailable"] = ["Report data is not configured", "Los datos de denuncias no están configurados", "Les données de signalement ne sont pas configurées", "I dati delle segnalazioni non sono configurati", "Os dados de denúncias não estão configurados", "신고 데이터가 설정되지 않았습니다", "通報データは設定されていません", "举报数据尚未配置", "檢舉資料尚未設定", "Dữ liệu báo cáo chưa được cấu hình"],
        ["admin.reports.unavailable.desc"] = ["Families currently has no report storage or moderation workflow. This page intentionally shows no fabricated counts.", "Families no dispone actualmente de almacenamiento de denuncias ni de un flujo de moderación. Esta página no muestra cifras inventadas.", "Families ne dispose actuellement d’aucun stockage des signalements ni processus de modération. Cette page n’affiche volontairement aucun chiffre fictif.", "Families attualmente non dispone di un archivio delle segnalazioni né di un flusso di moderazione. Questa pagina non mostra volutamente conteggi fittizi.", "O Families ainda não tem armazenamento de denúncias nem fluxo de moderação. Esta página não exibe contagens inventadas.", "현재 Families에는 신고 저장소나 검토 절차가 없습니다. 이 페이지에는 임의로 만든 수치를 표시하지 않습니다.", "現在 Families には通報データの保存先やモデレーションフローがありません。このページでは架空の件数を表示しません。", "Families 目前没有举报数据存储或审核流程，因此本页不会显示虚构的数量。", "Families 目前沒有檢舉資料儲存或審查流程，因此本頁不會顯示虛構數量。", "Families hiện chưa có nơi lưu báo cáo hoặc quy trình kiểm duyệt. Trang này chủ ý không hiển thị số liệu giả."],
        ["admin.upload.policy"] = ["Global upload policy", "Política global de carga", "Règles globales d’envoi", "Criteri globali di caricamento", "Política global de upload", "전체 업로드 정책", "全体アップロードポリシー", "全局上传策略", "全域上傳政策", "Chính sách tải lên toàn hệ thống"],
        ["admin.upload.policy.desc"] = ["Set service-wide per-file upload limits. Album-specific overrides take priority.", "Establece límites por archivo para todo el servicio. Los ajustes específicos del álbum tienen prioridad.", "Définissez les limites par fichier pour l’ensemble du service. Les réglages propres à un album sont prioritaires.", "Imposta i limiti per file per l’intero servizio. Le impostazioni specifiche dell’album hanno la precedenza.", "Defina limites por arquivo para todo o serviço. As configurações específicas do álbum têm prioridade.", "서비스 전체의 파일당 업로드 제한을 설정합니다. 앨범별 설정이 우선 적용됩니다.", "サービス全体のファイル単位アップロード上限を設定します。アルバム固有の設定が優先されます。", "设置全服务范围内的单文件上传限制。相册专属设置优先。", "設定全服務範圍的單一檔案上傳限制。相簿專屬設定優先。", "Đặt giới hạn tải lên cho từng tệp trên toàn dịch vụ. Cài đặt riêng của album được ưu tiên."],
        ["admin.image.file.limit"] = ["Image file limit", "Límite por archivo de imagen", "Limite par fichier image", "Limite per file immagine", "Limite por arquivo de imagem", "이미지 파일 제한", "画像ファイル上限", "图片文件限制", "圖片檔案限制", "Giới hạn tệp ảnh"],
        ["admin.image.file.limit.desc"] = ["Maximum size allowed for one image upload.", "Tamaño máximo permitido para una imagen.", "Taille maximale autorisée pour l’envoi d’une image.", "Dimensione massima consentita per una singola immagine.", "Tamanho máximo permitido para o upload de uma imagem.", "이미지 한 장을 업로드할 때 허용되는 최대 크기입니다.", "画像1枚のアップロードで許可される最大サイズです。", "单张图片允许上传的最大大小。", "單張圖片允許上傳的最大大小。", "Kích thước tối đa cho phép khi tải lên một ảnh."],
        ["admin.video.file.limit"] = ["Video file limit", "Límite por archivo de vídeo", "Limite par fichier vidéo", "Limite per file video", "Limite por arquivo de vídeo", "동영상 파일 제한", "動画ファイル上限", "视频文件限制", "影片檔案限制", "Giới hạn tệp video"],
        ["admin.video.file.limit.desc"] = ["Maximum size allowed for one video upload.", "Tamaño máximo permitido para un vídeo.", "Taille maximale autorisée pour l’envoi d’une vidéo.", "Dimensione massima consentita per un singolo video.", "Tamanho máximo permitido para o upload de um vídeo.", "동영상 하나를 업로드할 때 허용되는 최대 크기입니다.", "動画1本のアップロードで許可される最大サイズです。", "单个视频允许上传的最大大小。", "單部影片允許上傳的最大大小。", "Kích thước tối đa cho phép khi tải lên một video."],
        ["admin.save.all"] = ["Save all settings", "Guardar todos los ajustes", "Enregistrer tous les paramètres", "Salva tutte le impostazioni", "Salvar todas as configurações", "전체 설정 저장", "すべての設定を保存", "保存全部设置", "儲存全部設定", "Lưu tất cả cài đặt"],
        ["admin.metrics.scope"] = ["Available dashboard metrics", "Métricas disponibles en el panel", "Indicateurs disponibles sur le tableau de bord", "Metriche disponibili nella dashboard", "Métricas disponíveis no painel", "대시보드 제공 지표", "ダッシュボードで利用できる指標", "可用的仪表盘指标", "可用的儀表板指標", "Chỉ số hiện có trên bảng điều khiển"],
        ["admin.metrics.scope.desc"] = ["This dashboard uses only persisted album, post, comment, media and linked-user data. Visit analytics, report counts, total storage quotas and notification records are not stored yet, so they are not displayed.", "Este panel solo utiliza datos guardados de álbumes, publicaciones, comentarios, medios y usuarios vinculados. Las analíticas de visitas, el número de denuncias, las cuotas totales de almacenamiento y los registros de notificaciones aún no se guardan, por lo que no se muestran.", "Ce tableau de bord utilise uniquement les données enregistrées des albums, publications, commentaires, médias et utilisateurs associés. Les statistiques de visite, le nombre de signalements, les quotas de stockage globaux et les journaux de notification ne sont pas encore conservés et ne sont donc pas affichés.", "Questa dashboard utilizza solo i dati salvati di album, post, commenti, media e utenti collegati. Le statistiche delle visite, il numero di segnalazioni, le quote totali di archiviazione e i registri delle notifiche non sono ancora memorizzati e quindi non vengono mostrati.", "Este painel usa apenas dados salvos de álbuns, publicações, comentários, mídia e usuários vinculados. Estatísticas de visitas, contagens de denúncias, cotas totais de armazenamento e registros de notificações ainda não são armazenados e, por isso, não são exibidos.", "이 대시보드는 저장된 앨범, 게시물, 댓글, 미디어, 연결 사용자 데이터만 사용합니다. 방문 분석, 신고 건수, 전체 저장 용량 한도, 알림 기록은 아직 저장되지 않아 표시하지 않습니다.", "このダッシュボードでは、保存済みのアルバム、投稿、コメント、メディア、連携ユーザーデータのみを使用します。訪問分析、通報件数、総ストレージ容量、通知履歴はまだ保存されていないため表示しません。", "此仪表盘仅使用已保存的相册、帖子、评论、媒体和关联用户数据。访问分析、举报数量、总存储配额和通知记录尚未存储，因此不会显示。", "此儀表板僅使用已儲存的相簿、貼文、留言、媒體與關聯使用者資料。造訪分析、檢舉數量、總儲存配額與通知記錄尚未儲存，因此不會顯示。", "Bảng điều khiển này chỉ dùng dữ liệu album, bài đăng, bình luận, phương tiện và người dùng liên kết đã được lưu. Phân tích lượt truy cập, số báo cáo, hạn mức lưu trữ tổng và lịch sử thông báo chưa được lưu nên không hiển thị."],

